Contract ProcessSaleService::makeCashPayment(amount:Real): Boolean {

            precondition:
          self.CurrentSale.oclIsUndefined() = false and self.CurrentSale.IsComplete = false and self.CurrentSale.IsReadytoPay = true and amount >= self.CurrentSale.Amount

            postcondition:
          let payment:CashPayment in payment.oclIsNew() and payment.amountTendered = amount and payment.BelongedSale = self.CurrentSale and self.CurrentSale.AssoicatedPayment = payment and self.CurrentSale.Belongedstore = self.CurrentStore and Store.allInstance()->includes(self.CurrentStore) and self.CurrentStore.Sales->includes(self.CurrentSale) and self.CurrentSale.IsComplete = true and self.CurrentSale.Time = now() and payment.Balance = amount - self.CurrentSale.Amount and result = true

        }
